import {getRunConfiguration} from './app.mjs';
const panel=document.createElement('section');panel.className='panel';panel.innerHTML='<h2>Run HotSpot</h2><p>EV6 floorplan · gcc power trace<br>Steady-state simulation</p><p id="backend-status">Connecting to backend…</p><button id="run-hotspot" class="primary" disabled>Save configuration & run</button><h3>Saved runs</h3><select id="run-history" aria-label="Saved runs"><option value="">Select a saved run</option></select><div id="run-result" aria-live="polite"></div>';
document.querySelector('aside').prepend(panel);
const $=s=>panel.querySelector(s);let token;
async function api(path,options){const response=await fetch(path,options);const data=await response.json();if(!response.ok)throw Error(data.error||'Request failed');return data;}
async function history(){const runs=await api('/api/runs');$('#run-history').replaceChildren(new Option('Select a saved run',''),...runs.map(r=>new Option(`${new Date(r.created).toLocaleString()} · ${r.status}`,r.id)));}
function show(result){const target=$('#run-result');target.replaceChildren();const title=document.createElement('h3');title.textContent=`Run ${result.id.slice(0,8)} · ${result.status}`;target.append(title);const links=document.createElement('div');links.style.cssText='display:flex;flex-wrap:wrap;gap:12px;margin-top:12px';const config=document.createElement('a');config.href=`/api/runs/${result.id}/config`;config.download='submitted.config';config.textContent='Download saved configuration';links.append(config);for(const name of ['gcc.steady','gcc.ttrace']){const artifact=result.artifacts?.[name];if(!artifact)continue;const link=document.createElement('a');link.href=artifact.url;link.download=artifact.filename;link.textContent=`Download ${name}`;links.append(link);}target.append(links);if(result.rows.length){const table=document.createElement('table');table.style.width='100%';const header=table.createTHead().insertRow();for(const text of ['Node','°C']){const cell=document.createElement('th');cell.textContent=text;header.append(cell);}const body=table.createTBody();for(const row of result.rows){const tr=body.insertRow();tr.insertCell().textContent=row.name;tr.insertCell().textContent=row.celsius.toFixed(2);}const wrapper=document.createElement('div');wrapper.style.cssText='max-height:360px;overflow:auto;margin-top:15px';wrapper.append(table);target.append(wrapper);}const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Simulation log';const log=document.createElement('pre');log.textContent=result.log||'Run is still executing. Select it again to refresh.';details.append(summary,log);target.append(details);}
$('#run-hotspot').onclick=async()=>{const button=$('#run-hotspot');try{const config=getRunConfiguration();button.disabled=true;$('#backend-status').textContent='Configuration saved when accepted. Running HotSpot…';const result=await api('/api/runs',{method:'POST',headers:{'Content-Type':'application/json','X-Studio-Token':token},body:JSON.stringify({config})});show(result);await history();$('#backend-status').textContent=`Simulation ${result.status}.`;}catch(e){$('#backend-status').textContent=e.message;}finally{button.disabled=false;}};
$('#run-history').onchange=async e=>{if(e.target.value)try{show(await api(`/api/runs/${e.target.value}`));}catch(error){$('#backend-status').textContent=error.message;}};
try{const status=await api('/api/status');token=status.token;$('#backend-status').textContent=status.ready?'Backend ready · 60-second run limit':'Build HotSpot with setup.sh to enable runs.';$('#run-hotspot').disabled=!status.ready;document.querySelector('#solver').value='off';document.querySelector('#solver').dispatchEvent(new Event('change'));await history();}catch(e){$('#backend-status').textContent='Backend unavailable. Start Studio with server.py to run simulations.';}
